from typing import Annotated
from fastapi import Depends, FastAPI, Header
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from fastapi.testclient import TestClient
import pytest

app = FastAPI()
security = HTTPBearer()

@app.get("/users/me")
def read_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials, Depends(security)]
):
    return {"scheme": credentials.scheme, "credentials": credentials.credentials}

client = TestClient(app)

def test_bearer_single_space():
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx"})
    assert response.status_code == 200
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

def test_bearer_multiple_spaces():
    response = client.get("/users/me", headers={"Authorization": "Bearer   xxx"})
    assert response.status_code == 200
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

def test_bearer_trailing_whitespace():
    response = client.get("/users/me", headers={"Authorization": "Bearer xxx "})
    assert response.status_code == 200
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

def test_bearer_leading_trailing_whitespace():
    response = client.get("/users/me", headers={"Authorization": " Bearer  xxx  "})
    # Note: The 'Authorization' header value is typically stripped by the server/framework 
    # before it reaches get_authorization_scheme_param if it's the whole header.
    # But our function receives the value.
    # If the header is " Bearer  xxx  ", partition(" ") gives scheme=" ", param="Bearer  xxx  "
    # Wait, the current implementation is:
    # scheme, _, param = authorization_header_value.partition(" ")
    # If value is "Bearer  xxx  ", scheme="Bearer", param=" xxx  "
    # .strip() makes it "xxx"
    assert response.status_code == 200
    assert response.json() == {"scheme": "Bearer", "credentials": "xxx"}

